import{_ as e,o,c as r,a as n}from"./chunks/plugin-vue_export-helper.B1AaF8Z1.js";const l=JSON.parse('{"title":"Не могу не отреагировать на историю с кандидатом, который назвал вопрос…","description":"","frontmatter":{"site":"pro","title":"Не могу не отреагировать на историю с кандидатом, который назвал вопрос…","date":"2026-10-15T00:00:00.000Z","source":"https://t.me/jfyi_ps/109","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/posts/2026-10-15-ne-mogu-ne-otreagirovat-na-istoriyu-s"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Не могу не отреагировать на историю с кандидатом, который назвал вопрос…"}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/posts/2026-10-15-ne-mogu-ne-otreagirovat-na-istoriyu-s"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Не могу не отреагировать на историю с кандидатом, который назвал вопрос…"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BlogPosting\\",\\"headline\\":\\"Не могу не отреагировать на историю с кандидатом, который назвал вопрос…\\",\\"description\\":\\"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы.\\",\\"url\\":\\"https://oleg-sidorkin.ru/posts/2026-10-15-ne-mogu-ne-otreagirovat-na-istoriyu-s\\",\\"inLanguage\\":\\"ru-RU\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Oleg Sidorkin\\",\\"alternateName\\":\\"alterfo\\",\\"url\\":\\"https://oleg-sidorkin.ru\\",\\"jobTitle\\":\\"Software Engineer\\",\\"knowsAbout\\":[\\"Music\\",\\"Audio DSP\\",\\"AI\\",\\"RAG\\",\\"Frontend Development\\",\\"Solution Architecture\\"],\\"sameAs\\":[\\"https://github.com/alterfo\\"]},\\"datePublished\\":\\"2026-10-15\\"}"]]},"headers":[],"relativePath":"posts/2026-10-15-ne-mogu-ne-otreagirovat-na-istoriyu-s.md","filePath":"posts/2026-10-15-ne-mogu-ne-otreagirovat-na-istoriyu-s.md"}'),a={name:"posts/2026-10-15-ne-mogu-ne-otreagirovat-na-istoriyu-s.md"};function i(p,t,s,u,g,m){return o(),r("div",null,[...t[0]||(t[0]=[n("<p>Не могу не отреагировать на историю с кандидатом, который назвал вопрос собеседующего &quot;У нас уже 5 кандидатов, расскажите почему мы должны выбрать именно вас?&quot; манипуляцией и жестко отреагировал.</p><p>Тот факт что и та и другая сторона вышла с этим в публичное поле - в линк и тредсы, говорит о том что каждая считает что поступила правильно, но есть сомнения.</p><p>Сейчас читаю книгу &quot;Как общаться с мудаками&quot;, написана психиатром, который заметил, что большинство из нас встречается с психами чуть ли не каждый день.</p><p>Давайте попробуем разрулить эту ситуацию. Да, психи манипулируют, да, со своими целями, да, иногда вам нужно с ними общаться ради работы, или это ваши близкие.</p><p>Чтобы эффективно общаться с психами, не нужно им перечить, спорить, доказывать свою правоту, это бесполезно. Для общения с &quot;пограничниками&quot; (пограничное расстройство личности) уже давно выработана техника SET UP - проявить эмпатию и понимание, а потом мягко вернуть в реальность. В книге же даны техники, которые работают на всём огромном спектре психических расстройств.</p><p>Выходя из дома, я перечисляю предметы, которые я должен взять с собой. У психологов на автомат поставлены вопросы &quot;Кто я? (роль)&quot;, &quot;Что мне нужно в этой ситуации? (цель)&quot;, &quot;Что я буду делать по этому поводу? (план)&quot;</p><p>Вернёмся же к кандидату. Как же можно было ответить не вступая в бой. Во-первых, нужно помнить что любой ответ должен быть максимально аутентичным вам, иначе это будет звучать как издёвка, например &quot;мне не хватает информации, расскажите поподробнее об этих 5 кандидатах&quot; - это та же какашка, обернутая в вежливость.</p><p>&quot;Мне не хватает информации, чтобы сравнивать себя с другими. Подскажите, какие качества для вас сейчас приоритетны? А пока скажу, в чём я точно силён: ...&quot;</p><p>Или</p><p>&quot;Понимаю, что выбор непростой и конкуренция высокая. Давайте я скажу, что именно могу дать вашей команде. Если по ходу разговора у вас появятся сомнения, я с удовольствием на них отвечу&quot;</p><p>Это примеры ассертивных и аутентичных ответов. Цель психа - выбить вас из равновесия, чтобы вы потеряли контроль. Добиться эмоциональной реакции от вас. К этому просто нужно быть готовых, но не стоит видеть психов в каждом, иначе вы сами станете психом, который бесит людей своей токсичной вежливостью и псевдо-эмпатией. Это очень тонкая грань.</p><p>Успехов на собеседованиях!</p>",12)])])}const d=e(a,[["render",i]]);export{l as __pageData,d as default};
